package com.marketplace;
import java.util.*;import java.math.*;import java.time.*;import jakarta.servlet.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.transaction.annotation.Transactional;
@RestController @RequestMapping("/api/admin") public class Admin {
final Db d;final Access a;final Commerce c;final Orders orders;Admin(Db d,Access a,Commerce c,Orders o){this.d=d;this.a=a;this.c=c;orders=o;}
@GetMapping("/{resource}") Object list(HttpSession s,@PathVariable String resource){a.role(s,"ADMIN");return switch(resource){case "users"->d.all("select id,name,email,role,active from users order by id");case "sellers"->d.all("select s.*,u.email from stores s join users u on u.id=s.user_id order by s.id");case "products"->d.all("select p.id,p.title,p.active,s.name seller from products p join stores s on s.id=p.seller_id order by p.id");case "categories"->d.all("select * from categories order by id");case "orders"->d.all("select id,user_id,payment_state,total,created_at from orders order by id desc limit 200");case "returns"->d.all("select * from returns order by id desc");case "refunds"->d.all("select * from refunds order by id desc");case "promotions"->d.all("select * from promotions order by code");case "audit"->d.all("select * from audit_logs order by id desc limit 200");case "outbox"->d.all("select * from outbox order by id desc limit 200");case "reviews"->d.all("select * from reviews order by id desc");default->throw new Failure(404,"NOT_FOUND","Unknown administration view");};}
@GetMapping("/orders/{id}") Object order(HttpSession s,@PathVariable long id){a.role(s,"ADMIN");return orders.detail(id);}
record Active(boolean active){}
@PostMapping("/{resource}/{id}/active") @Transactional Object active(HttpSession s,@PathVariable String resource,@PathVariable long id,@RequestBody Active b){long uid=a.role(s,"ADMIN");String table=switch(resource){case "users"->"users";case "sellers"->"stores";case "products"->"products";case "reviews"->"reviews";default->throw new IllegalArgumentException();};if(table.equals("users")&&d.one("select role from users where id=?",id).get("role").equals("ADMIN"))throw new Failure(409,"ADMIN_PROTECTED","Administrator accounts cannot be suspended here");if(d.exec("update "+table+" set "+(table.equals("reviews")?"visible":"active")+"=? where id=?",b.active(),id)!=1)throw new Failure(404,"NOT_FOUND","Resource not found");audit(uid,"SET_ACTIVE",resource+":"+id,"active="+b.active());return Map.of("ok",true);}
@PostMapping("/categories") @Transactional Object category(HttpSession s,@RequestBody Map<String,String>b){long uid=a.role(s,"ADMIN");Catalog.check(b.get("name"),2,100);long id=d.id("insert into categories(name) values(?) returning id",b.get("name"));audit(uid,"CATEGORY_CREATED","category:"+id,b.get("name"));return Map.of("id",id);}
@PutMapping("/categories/{id}") @Transactional Object categoryEdit(HttpSession s,@PathVariable long id,@RequestBody Map<String,String>b){long uid=a.role(s,"ADMIN");Catalog.check(b.get("name"),2,100);d.exec("update categories set name=? where id=?",b.get("name"),id);audit(uid,"CATEGORY_UPDATED","category:"+id,b.get("name"));return Map.of("ok",true);}
record Promo(String code,String kind,BigDecimal amount,BigDecimal minimum,BigDecimal maxDiscount,Instant starts,Instant ends,int usageLimit,int perUser){}
@PostMapping("/promotions") @Transactional Object promo(HttpSession s,@RequestBody Promo p){long uid=a.role(s,"ADMIN");if(p.code()==null||!p.code().matches("[A-Z0-9]{3,30}")||!List.of("PERCENT","FIXED").contains(p.kind())||p.amount()==null||p.amount().signum()<=0||p.minimum()==null||p.minimum().signum()<0||p.maxDiscount()==null||p.maxDiscount().signum()<0||p.starts()==null||p.ends()==null||!p.ends().isAfter(p.starts())||p.usageLimit()<1||p.perUser()<1||(p.kind().equals("PERCENT")&&p.amount().compareTo(new BigDecimal("100"))>0))throw new IllegalArgumentException();d.exec("insert into promotions(code,kind,amount,minimum,max_discount,starts,ends,usage_limit,per_user) values(?,?,?,?,?,?,?,?,?)",p.code(),p.kind(),p.amount(),p.minimum(),p.maxDiscount(),java.sql.Timestamp.from(p.starts()),java.sql.Timestamp.from(p.ends()),p.usageLimit(),p.perUser());audit(uid,"PROMOTION_CREATED",p.code(),p.kind());return Map.of("ok",true);}
@PostMapping("/promotions/{code}/expire") @Transactional Object expire(HttpSession s,@PathVariable String code){long uid=a.role(s,"ADMIN");d.exec("update promotions set ends=now() where code=?",code);audit(uid,"PROMOTION_EXPIRED",code,"Ended immediately");return Map.of("ok",true);}
@PostMapping("/orders/{id}/late-refund") @Transactional Object late(HttpSession s,@PathVariable long id){long uid=a.role(s,"ADMIN");var o=d.one("select * from orders where id=? for update",id);if(o.get("payment_state").equals("REFUNDED"))return o;if(!o.get("payment_state").equals("REFUND_REQUIRED"))throw new Failure(409,"INVALID_STATE","Only late payments awaiting refund may use this action");for(var so:d.all("select id from seller_orders where order_id=?",id)){BigDecimal amount=(BigDecimal)d.one("select sum(unit_price*quantity-discount+tax+shipping) amount from order_items where seller_order_id=?",so.get("id")).get("amount");d.exec("insert into refunds(order_id,seller_order_id,amount) values(?,?,?) on conflict do nothing",id,so.get("id"),amount);}d.exec("update orders set payment_state='REFUNDED' where id=?",id);d.exec("update seller_orders set fulfillment='CANCELLED' where order_id=?",id);c.notify(Db.n(o,"user_id"),"Late payment for order #"+id+" refunded by demo provider.");audit(uid,"LATE_PAYMENT_REFUNDED","order:"+id,"Demo refund; no stock restock needed");return Map.of("ok",true);}
void audit(long uid,String action,String resource,String summary){d.exec("insert into audit_logs(actor,action,resource,summary) values(?,?,?,?)",uid,action,resource,summary);}
}
